  dimension_style_handle_high INTEGER NOT NULL CHECK(dimension_style_handle_high BETWEEN 0 AND 4294967295), dimension_style_handle_low INTEGER NOT NULL CHECK(dimension_style_handle_low BETWEEN 0 AND 4294967295), dimension_block_handle_high INTEGER CHECK(dimension_block_handle_high BETWEEN 0 AND 4294967295), dimension_block_handle_low INTEGER CHECK(dimension_block_handle_low BETWEEN 0 AND 4294967295), oblique_angle_class TEXT NOT NULL CHECK(oblique_angle_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), oblique_angle_ieee754_bits INTEGER, oblique_angle REAL CHECK((oblique_angle_class = 'finite' AND oblique_angle IS NOT NULL AND abs(oblique_angle) <= 1.7976931348623157e308) OR (oblique_angle_class != 'finite' AND oblique_angle IS NULL)), dimension_rotation_class TEXT NOT NULL CHECK(dimension_rotation_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), dimension_rotation_ieee754_bits INTEGER, dimension_rotation REAL CHECK((dimension_rotation_class = 'finite' AND dimension_rotation IS NOT NULL AND abs(dimension_rotation) <= 1.7976931348623157e308) OR (dimension_rotation_class != 'finite' AND dimension_rotation IS NULL)), CHECK((dimension_block_handle_high IS NULL) = (dimension_block_handle_low IS NULL))
