  id INTEGER PRIMARY KEY REFERENCES dwg_viewport_entity(id), color_index INTEGER NOT NULL CHECK(color_index BETWEEN 0 AND 65535), kind TEXT NOT NULL CHECK(kind IN ('none','by_layer','by_block','by_color','by_aci','by_pen','foreground','layer_off','layer_frozen')),
  red INTEGER CHECK(red BETWEEN 0 AND 255), green INTEGER CHECK(green BETWEEN 0 AND 255), blue INTEGER CHECK(blue BETWEEN 0 AND 255), value_index INTEGER CHECK(value_index BETWEEN 0 AND 65535), name TEXT, book_name TEXT,
  CHECK((kind = 'by_color' AND red IS NOT NULL AND green IS NOT NULL AND blue IS NOT NULL) OR (kind != 'by_color' AND red IS NULL AND green IS NULL AND blue IS NULL)),
  CHECK((kind = 'by_aci' AND value_index IS NOT NULL) OR (kind = 'by_pen' AND value_index IS NOT NULL AND value_index <= 255) OR (kind NOT IN ('by_aci','by_pen') AND value_index IS NULL))
);
